//! Tests for post-quantum sealing (X25519 + ML-KEM-768, X-Wing construction) and the identity key binding (ML-DSA-65).
//!
//! - `tests/vectors/acvp-ml-kem-768.json`, `acvp-ml-dsa-65.json`: extracted from the NIST ACVP vectors (`extract_acvp.py`)
//! - `tests/vectors/xwing-draft06.json`: the draft-connolly-cfrg-xwing-kem-06 test vectors, as shipped in the x-wing 0.1.1 crate
//! - `tests/vectors/pq-rust.json`: generated by this file from fixed randomness; opened by the JavaScript reference
//!   implementation (@noble/post-quantum). To regenerate: `GORI_WRITE_VECTORS=1 cargo test --test pq`
//! - Quick benchmark: `cargo test --release --test pq -- --ignored --nocapture measure`

use std::ffi::CStr;
use std::path::PathBuf;
use std::time::Instant;

use gori_core::core::{OuterPurpose, INNER_ENVELOPE_LEN, OUTER_ENVELOPE_LEN};
use gori_core::ffi::{self, GoriBuf};
use gori_core::pq::{self, EncKeys, IdSeeds, RecipientKey, CT_LEN, CT_M_LEN, DSA_SIG_LEN, HEK_LEN, PK_D_LEN, PK_M_LEN};
use gori_core::{crypto, Core, Error, Slot};
use rand_chacha::rand_core::{CryptoRng, Error as RandError, RngCore, SeedableRng};
use rand_chacha::ChaCha20Rng;
use serde::{Deserialize, Serialize};

fn h(s: &str) -> Vec<u8> {
    hex::decode(s).unwrap_or_else(|_| panic!("hex: {s}"))
}

fn x(b: &[u8]) -> String {
    hex::encode(b)
}

fn arr<const N: usize>(s: &str) -> [u8; N] {
    h(s).try_into().unwrap_or_else(|_| panic!("length {N}: {s}"))
}

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/vectors")
}

fn read_json<T: for<'de> Deserialize<'de>>(name: &str) -> T {
    let p = dir().join(name);
    serde_json::from_str(&std::fs::read_to_string(&p).unwrap_or_else(|_| panic!("vector file not found: {}", p.display())))
        .unwrap()
}

fn seeded(seed: u64) -> Core {
    Core::with_rng(Box::new(ChaCha20Rng::seed_from_u64(seed)))
}

fn random<const N: usize>(r: &mut ChaCha20Rng) -> [u8; N] {
    let mut a = [0u8; N];
    r.fill_bytes(&mut a);
    a
}

/// An RNG that hands out preset bytes in order (to replay the randomness another implementation used). Panics if it runs out
struct Replay(Vec<u8>);

impl RngCore for Replay {
    fn next_u32(&mut self) -> u32 {
        let mut b = [0u8; 4];
        self.fill_bytes(&mut b);
        u32::from_le_bytes(b)
    }
    fn next_u64(&mut self) -> u64 {
        let mut b = [0u8; 8];
        self.fill_bytes(&mut b);
        u64::from_le_bytes(b)
    }
    fn fill_bytes(&mut self, dest: &mut [u8]) {
        assert!(self.0.len() >= dest.len(), "Replay: drew more random bytes than were preset");
        let rest = self.0.split_off(dest.len());
        dest.copy_from_slice(&self.0);
        self.0 = rest;
    }
    fn try_fill_bytes(&mut self, dest: &mut [u8]) -> Result<(), RandError> {
        self.fill_bytes(dest);
        Ok(())
    }
}

impl CryptoRng for Replay {}

/// A core loaded with an encryption seed (the recipient)
fn receiver(seed: u64) -> (Core, [u8; HEK_LEN]) {
    let mut c = seeded(seed);
    c.generate(Slot::Enc);
    let hek = c.encryption_hybrid_key().unwrap();
    (c, hek)
}

// ── NIST ACVP ML-KEM-768 ──

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct AcvpKem {
    key_gen: Vec<KemKeyGen>,
    encapsulation: Vec<KemEncap>,
    encapsulation_key_check: Vec<KemCheck>,
}
#[derive(Deserialize)]
struct KemKeyGen {
    d: String,
    z: String,
    ek: String,
}
#[derive(Deserialize)]
struct KemEncap {
    ek: String,
    m: String,
    c: String,
    k: String,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct KemCheck {
    tc_id: u32,
    ek: String,
    test_passed: bool,
}

type MlKemDk = ml_kem::DecapsulationKey<ml_kem::MlKem768>;
type MlKemEk = ml_kem::EncapsulationKey<ml_kem::MlKem768>;

/// keyGen(d, z) and encaps(ek, m), using exactly the two calls the core makes (`DecapsulationKey::from_seed`,
/// `encapsulate_deterministic`). The public key (modulus) check goes through our own [`RecipientKey::parse`]
#[test]
fn acvp_ml_kem_768() {
    use ml_kem::array::Array;
    use ml_kem::KeyExport;
    let v: AcvpKem = read_json("acvp-ml-kem-768.json");
    assert_eq!(v.key_gen.len(), 25);
    for t in &v.key_gen {
        let mut seed = h(&t.d);
        seed.extend(h(&t.z));
        let dk = MlKemDk::from_seed(Array::try_from(seed.as_slice()).unwrap());
        assert_eq!(x(&dk.encapsulation_key().to_bytes()), t.ek.to_lowercase(), "keyGen");
    }
    assert!(!v.encapsulation.is_empty());
    for t in &v.encapsulation {
        let ek = MlKemEk::new(&Array::try_from(h(&t.ek).as_slice()).unwrap()).unwrap();
        let (c, k) = ek.encapsulate_deterministic(&Array::try_from(h(&t.m).as_slice()).unwrap());
        assert_eq!((x(&c), x(&k)), (t.c.to_lowercase(), t.k.to_lowercase()), "encaps");
    }
    // Check with a HEK that carries an honest X25519 public key, so the verdict rests on the pk_M modulus check alone
    let pk_x = EncKeys::from_seed(&[1u8; 32]).pk_x();
    assert!(v.encapsulation_key_check.iter().any(|t| !t.test_passed));
    for t in &v.encapsulation_key_check {
        let mut hek = h(&t.ek);
        hek.extend_from_slice(&pk_x);
        let got = RecipientKey::parse(&hek);
        if t.test_passed {
            assert!(got.is_ok(), "tc {}: valid key rejected", t.tc_id);
        } else {
            assert!(matches!(got.err(), Some(Error::WeakKey) | Some(Error::NeedHybridKey)), "tc {}: invalid key accepted", t.tc_id);
        }
    }
}

// ── X-Wing draft 06 ──

#[derive(Deserialize)]
struct XWingVector {
    seed: String,
    eseed: String,
    ss: String,
    sk: String,
    pk: String,
    ct: String,
}

/// draft-connolly-cfrg-xwing-kem-06 test vectors: our byte layout (seed expansion, HEK order, ct order, combiner) matches the draft
#[test]
fn xwing_draft06_vectors() {
    let vs: Vec<XWingVector> = read_json("xwing-draft06.json");
    assert_eq!(vs.len(), 3);
    for v in &vs {
        assert_eq!(v.sk, v.seed, "draft 06: private key = 32-byte seed");
        let seed: [u8; 32] = arr(&v.seed);
        let keys = EncKeys::from_seed(&seed);
        assert_eq!(x(&keys.hek()), v.pk, "public key = pk_M ‖ pk_X");
        let to = RecipientKey::parse(&h(&v.pk)).unwrap();
        let (ct, ss) = to.encapsulate_derand(&arr(&v.eseed)).unwrap();
        assert_eq!(x(&ct), v.ct, "ct = ct_M ‖ ct_X");
        assert_eq!(x(&ss[..]), v.ss, "combiner");
        assert_eq!(x(&keys.decapsulate(&ct).unwrap()[..]), v.ss);
    }
}

/// Same seed and randomness as the x-wing 0.1.1 crate → same public key, ct and ss; each side opens the other's ct
#[test]
fn cross_with_x_wing_crate() {
    use x_wing::{Decapsulate, Decapsulator, KeyExport};
    let mut r = ChaCha20Rng::seed_from_u64(0x7877);
    for _ in 0..16 {
        let seed: [u8; 32] = random(&mut r);
        let eseed: [u8; 64] = random(&mut r);
        let theirs = x_wing::DecapsulationKey::from(seed);
        let ours = EncKeys::from_seed(&seed);
        assert_eq!(&theirs.encapsulation_key().to_bytes()[..], &ours.hek()[..]);
        let (their_ct, their_ss) = theirs.encapsulation_key().encapsulate_deterministic(&eseed.into());
        let (ct, ss) = RecipientKey::parse(&ours.hek()).unwrap().encapsulate_derand(&eseed).unwrap();
        assert_eq!(&their_ct[..], &ct[..]);
        assert_eq!(&their_ss[..], &ss[..]);
        assert_eq!(&theirs.decapsulate(&ct.into())[..], &ss[..]);
        assert_eq!(&ours.decapsulate(&their_ct).unwrap()[..], &their_ss[..]);
    }
}

// ── Outer envelope v2 ──

/// Round trip: exactly 1201 bytes, for every purpose, and an envelope does not open under another purpose.
/// An envelope addressed to someone else's key gives `NotForMe`
#[test]
fn outer_envelope_round_trip_exact_length() {
    let mut sender = seeded(1);
    let (mut recv, hek) = receiver(2);
    let (mut other, _) = receiver(3);
    let h1 = sender.create_content_key();
    // Non-ASCII plaintext (test data)
    let ct = sender.encrypt(&h1, "outer-layer key \u{2713}".as_bytes()).unwrap();
    for p in OuterPurpose::ALL {
        let env = sender.seal_outer(&h1, p, &hek).unwrap();
        assert_eq!(env.len(), OUTER_ENVELOPE_LEN);
        assert_eq!(OUTER_ENVELOPE_LEN, 1201);
        assert_eq!(env[0], crypto::OUTER_V2);
        let opened = recv.open_outer(p, &env).unwrap();
        assert_eq!(&recv.decrypt(&opened, &ct).unwrap()[..], "outer-layer key \u{2713}".as_bytes());
        for q in OuterPurpose::ALL.into_iter().filter(|q| *q != p) {
            assert_eq!(recv.open_outer(q, &env).unwrap_err(), Error::NotForMe, "{p:?} → {q:?}");
        }
        assert_eq!(other.open_outer(p, &env).unwrap_err(), Error::NotForMe);
    }
    assert_eq!(seeded(4).open_outer(OuterPurpose::Envelope, &[0u8; OUTER_ENVELOPE_LEN]).unwrap_err(), Error::NoEncryptionKey);
    assert_eq!(sender.seal_outer("no-such-handle", OuterPurpose::Envelope, &hek).unwrap_err(), Error::UnknownHandle);
}

/// Flipping any single byte (version, ct_M, ct_X, nonce, body) makes opening fail. A ct that is wrong only in its ML-KEM part
/// also fails, and decaps then returns a different ss by implicit rejection (deterministic: the same ct gives the same wrong value)
#[test]
fn every_flipped_byte_fails() {
    let mut sender = seeded(5);
    let (mut recv, hek) = receiver(6);
    let k = sender.create_content_key();
    let env = sender.seal_outer(&k, OuterPurpose::Envelope, &hek).unwrap();
    let ct_x = 1 + CT_M_LEN;
    let nonce = 1 + CT_LEN;
    let body = nonce + 24;
    let mut positions: Vec<usize> = vec![0];
    positions.extend((1..ct_x).step_by(7));
    positions.extend(ct_x..OUTER_ENVELOPE_LEN);
    for i in positions {
        let mut bad = env.clone();
        bad[i] ^= 0x01;
        let err = recv.open_outer(OuterPurpose::Envelope, &bad).unwrap_err();
        let want = if i == 0 { Error::BadEnvelope } else { Error::NotForMe };
        assert_eq!(err, want, "byte {i} (ct_X {ct_x}, nonce {nonce}, body {body})");
    }
    // A ct that is wrong only in its ML-KEM part
    let keys = EncKeys::from_seed(&recv.slot_secret(Slot::Enc).unwrap());
    let good = keys.decapsulate(&env[1..1 + CT_LEN]).unwrap();
    let mut ct = env[1..1 + CT_LEN].to_vec();
    ct[100] ^= 0x40;
    let rejected = keys.decapsulate(&ct).unwrap();
    assert_ne!(*rejected, *good);
    assert_eq!(*keys.decapsulate(&ct).unwrap(), *rejected, "implicit rejection is deterministic");
}

/// Wrong lengths and versions are rejected. A 104-byte inner envelope given to the outer opener, and a 1201-byte outer
/// envelope given to the inner opener, both give `BadEnvelope`
#[test]
fn lengths_versions_and_layers() {
    let mut sender = seeded(7);
    let (mut recv, hek) = receiver(8);
    let pk_x = recv.public_key(Slot::Enc).unwrap();
    assert_eq!(&hek[PK_M_LEN..], &pk_x[..], "last 32 bytes of HEK = the current encryption public key");
    let k = sender.create_content_key();
    let outer = sender.seal_outer(&k, OuterPurpose::Note, &hek).unwrap();
    for n in [0, 1, 104, 1169, 1200, 1202, 2402] {
        let mut v = outer.clone();
        v.resize(n, 0);
        assert_eq!(recv.open_outer(OuterPurpose::Note, &v).unwrap_err(), Error::BadEnvelope, "length {n}");
    }
    for ver in [0x00u8, 0x01, 0x03, 0xff] {
        let mut v = outer.clone();
        v[0] = ver;
        assert_eq!(recv.open_outer(OuterPurpose::Note, &v).unwrap_err(), Error::BadEnvelope, "version {ver}");
    }
    // Inner and outer envelopes are not interchangeable
    let inner = sender.seal_inner(&k, &pk_x).unwrap();
    assert_eq!(inner.len(), INNER_ENVELOPE_LEN);
    assert_eq!(recv.open_outer(OuterPurpose::Envelope, &inner).unwrap_err(), Error::BadEnvelope);
    assert!(recv.open_inner(&inner).is_ok());
    assert_eq!(recv.open_inner(&outer).unwrap_err(), Error::BadEnvelope);
    // The core refuses to seal the outer layer to a 32-byte key
    assert_eq!(sender.seal_outer(&k, OuterPurpose::Envelope, &pk_x).unwrap_err(), Error::NeedHybridKey);
    // The inner layer takes only a 32-byte key
    assert_eq!(sender.seal_inner(&k, &hek).unwrap_err(), Error::InvalidArgument);
}

/// Recipient hiding: envelopes sealed to the same HEK share no fixed byte other than the version byte, and the kid never
/// appears in the clear. Envelopes for different recipients have the same shape (length, version)
#[test]
fn envelopes_do_not_reveal_the_recipient() {
    let mut sender = seeded(9);
    let (_, hek) = receiver(10);
    let (_, hek2) = receiver(11);
    let k = sender.create_content_key();
    let envs: Vec<Vec<u8>> = (0..8).map(|_| sender.seal_outer(&k, OuterPurpose::Envelope, &hek).unwrap()).collect();
    for i in 1..OUTER_ENVELOPE_LEN {
        assert!(envs.iter().any(|e| e[i] != envs[0][i]), "position {i} is the same in every envelope");
    }
    let kid = crypto::kid(&hek);
    for e in &envs {
        assert!(!e.windows(crypto::KID_LEN).any(|w| w == kid), "kid appears in the clear");
        assert!(!e.windows(32).any(|w| w == &hek[PK_M_LEN..]), "pk_X appears in the clear");
        assert!(!e.windows(32).any(|w| w == &hek[..32]), "the start of pk_M appears in the clear");
    }
    let e2 = sender.seal_outer(&k, OuterPurpose::Envelope, &hek2).unwrap();
    assert_eq!((e2.len(), e2[0]), (envs[0].len(), envs[0][0]));
}

/// The kid is checked inside the AEAD: even when the AEAD opens, an inner kid that is not my HEK's gives `NotForMe`
/// (for users with several devices). Also pins the wrap key construction (HKDF(ss, no salt, context ‖ 0x00 ‖ 0x02))
/// and the AAD (version ‖ ct)
#[test]
fn inner_kid_is_checked_and_kdf_is_pinned() {
    let (mut recv, hek) = receiver(12);
    let to = RecipientKey::parse(&hek).unwrap();
    let eseed = [0x5au8; 64];
    let (ct, ss) = to.encapsulate_derand(&eseed).unwrap();
    let mut info = OuterPurpose::Keep.info().to_vec();
    info.extend_from_slice(&[0, 2]);
    let wrap = crypto::hkdf32(&ss[..], None, &info);
    let nonce = [3u8; 24];
    let build = |kid: &[u8]| {
        let mut aad = vec![2u8];
        aad.extend_from_slice(&ct);
        let mut inner = kid.to_vec();
        inner.extend_from_slice(&[0x77u8; 32]);
        let mut env = aad.clone();
        env.extend_from_slice(&nonce);
        env.extend_from_slice(&crypto::seal(&wrap, &nonce, &aad, &inner));
        env
    };
    let good = build(&crypto::kid(&hek));
    assert_eq!(good.len(), OUTER_ENVELOPE_LEN);
    assert!(recv.open_outer(OuterPurpose::Keep, &good).is_ok(), "a hand-built envelope matches the core's format");
    let mut wrong = crypto::kid(&hek);
    wrong[0] ^= 1;
    assert_eq!(recv.open_outer(OuterPurpose::Keep, &build(&wrong)).unwrap_err(), Error::NotForMe);
    // kid = SHA-256("gori-pq/kid-v1\0" ‖ HEK)[..8]
    use sha2::{Digest, Sha256};
    let mut d = Sha256::new();
    d.update(b"gori-pq/kid-v1\0");
    d.update(hek);
    assert_eq!(&d.finalize()[..8], &crypto::kid(&hek)[..]);
}

/// Same seed → same HEK, ik and pk_D (deterministic); a different seed → different keys. pk_X is the last 32 bytes of HEK
#[test]
fn keys_are_deterministic_from_seeds() {
    let seed = [0x42u8; 32];
    let mut a = seeded(13);
    let mut b = seeded(14);
    for c in [&mut a, &mut b] {
        c.load(Slot::Enc, &seed).unwrap();
        c.load(Slot::Account, &seed).unwrap();
    }
    assert_eq!(a.encryption_hybrid_key().unwrap(), b.encryption_hybrid_key().unwrap());
    assert_eq!(a.public_key(Slot::Account).unwrap(), b.public_key(Slot::Account).unwrap());
    assert_eq!(a.pq_sig_binding().unwrap().pk_d, b.pq_sig_binding().unwrap().pk_d);
    let mut c = seeded(15);
    c.load(Slot::Enc, &[0x43u8; 32]).unwrap();
    assert_ne!(c.encryption_hybrid_key().unwrap(), a.encryption_hybrid_key().unwrap());
    // The public keys differ from the old interpretation (seed used directly as the Ed25519/X25519 secret),
    // which is why an old-format vault must never be loaded silently
    assert_ne!(a.public_key(Slot::Account).unwrap(), crypto::ed25519_public(&seed));
    assert_ne!(a.public_key(Slot::Enc).unwrap(), crypto::x25519_public(&seed));
    // The device key has no seed expansion
    a.load(Slot::Device, &seed).unwrap();
    assert_eq!(a.public_key(Slot::Device).unwrap(), crypto::ed25519_public(&seed));
}

/// A HEK with only pk_M replaced (a server or man in the middle swapping just pk_M) fails es3 verification.
/// es3 also does not verify as a v2 statement
#[test]
fn es3_covers_the_ml_kem_key() {
    let mut me = seeded(16);
    let ik = me.generate(Slot::Account);
    me.generate(Slot::Enc);
    let hek = me.encryption_hybrid_key().unwrap();
    let es3 = me.sign_encryption_key_v3().unwrap();
    assert!(Core::verify(&ik, &crypto::enc_key_v3_message(&hek), &es3));
    let (_, other) = receiver(17);
    let mut swapped = hek;
    swapped[..PK_M_LEN].copy_from_slice(&other[..PK_M_LEN]);
    assert!(!Core::verify(&ik, &crypto::enc_key_v3_message(&swapped), &es3));
    let mut flipped = hek;
    flipped[500] ^= 1;
    assert!(!Core::verify(&ik, &crypto::enc_key_v3_message(&flipped), &es3));
    let pk_x: [u8; 32] = hek[PK_M_LEN..].try_into().unwrap();
    assert!(!Core::verify(&ik, &crypto::enc_key_message(&pk_x), &es3));
    let es2 = me.sign_encryption_key().unwrap();
    assert!(!Core::verify(&ik, &crypto::enc_key_v3_message(&hek), &es2));
    // A plain signature cannot produce it
    assert_eq!(me.sign(Slot::Account, &crypto::enc_key_v3_message(&hek)).unwrap_err(), Error::ReservedStatement);
    assert_eq!(crypto::enc_key_v3_message(&hek).len(), 21 + 32 + PK_M_LEN);
}

/// HEK checks: a pk_M modulus failure or a weak pk_X gives `WeakKey` (nothing is sealed); a wrong length gives `NeedHybridKey`
#[test]
fn bad_hybrid_keys_are_refused() {
    let mut sender = seeded(18);
    let k = sender.create_content_key();
    let (_, hek) = receiver(19);
    assert!(Core::check_hybrid_key(&hek).is_ok());
    // Push one pk_M coefficient to q (3329) or above: set the first 12 bits to 0xfff
    let mut bad_m = hek;
    bad_m[0] = 0xff;
    bad_m[1] |= 0x0f;
    assert_eq!(Core::check_hybrid_key(&bad_m).unwrap_err(), Error::WeakKey);
    assert_eq!(sender.seal_outer(&k, OuterPurpose::Envelope, &bad_m).unwrap_err(), Error::WeakKey);
    for weak_x in [[0u8; 32], { let mut o = [0u8; 32]; o[0] = 1; o }, { let mut hi = [0u8; 32]; hi.copy_from_slice(&hek[PK_M_LEN..]); hi[31] |= 0x80; hi }] {
        let mut bad_x = hek;
        bad_x[PK_M_LEN..].copy_from_slice(&weak_x);
        assert_eq!(Core::check_hybrid_key(&bad_x).unwrap_err(), Error::WeakKey);
        assert_eq!(sender.seal_outer(&k, OuterPurpose::Envelope, &bad_x).unwrap_err(), Error::WeakKey);
    }
    for n in [0usize, 32, 1184, 1215, 1217] {
        assert_eq!(Core::check_hybrid_key(&vec![1u8; n]).unwrap_err(), Error::NeedHybridKey, "length {n}");
    }
}

/// Old-format vault names give `StaleKey` and load nothing. The new names double as format markers
#[test]
fn stale_vault_names_are_refused() {
    let mut c = seeded(20);
    assert_eq!(Slot::Account.vault_name(), "account-seed-v2");
    assert_eq!(Slot::Enc.vault_name(), "enc-seed-v2");
    assert_eq!(Slot::Device.vault_name(), "device");
    assert_eq!(Slot::Recovery.vault_name(), "recovery");
    for old in ["account", "enc"] {
        assert_eq!(c.load_vault(old, &[1u8; 32]).unwrap_err(), Error::StaleKey);
    }
    assert!(Slot::ALL.iter().all(|s| !c.has(*s)));
    assert_eq!(c.load_vault("account-seed-v1", &[1u8; 32]).unwrap_err(), Error::InvalidArgument);
    assert_eq!(c.load_vault("", &[1u8; 32]).unwrap_err(), Error::InvalidArgument);
    for s in Slot::ALL {
        let (slot, p) = c.load_vault(s.vault_name(), &[7u8; 32]).unwrap();
        assert_eq!((slot, p), (s, s.public_from(&[7u8; 32])));
    }
}

// ── Identity key ML-DSA-65 ──

#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct AcvpDsa {
    key_gen: Vec<DsaKeyGen>,
    sig_ver: Vec<DsaSigVer>,
}
#[derive(Deserialize)]
struct DsaKeyGen {
    seed: String,
    pk: String,
}
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
struct DsaSigVer {
    tc_id: u32,
    pk: String,
    message: String,
    context: String,
    signature: String,
    test_passed: bool,
}

/// NIST ACVP ML-DSA-65 keyGen(ξ) and sigVer (pure, with context), run through the core's own key generation and verification
#[test]
fn acvp_ml_dsa_65() {
    let v: AcvpDsa = read_json("acvp-ml-dsa-65.json");
    assert!(!v.key_gen.is_empty());
    for t in &v.key_gen {
        assert_eq!(x(&pq::dsa_public_for_tests(&arr(&t.seed))), t.pk.to_lowercase(), "keyGen");
    }
    assert!(v.sig_ver.iter().any(|t| t.test_passed) && v.sig_ver.iter().any(|t| !t.test_passed));
    for t in &v.sig_ver {
        assert_eq!(pq::dsa_verify(&h(&t.pk), &h(&t.message), &h(&t.context), &h(&t.signature)), t.test_passed, "sigVer tc {}", t.tc_id);
    }
}

/// Our signing (M' = 0 ‖ |ctx| ‖ ctx ‖ M fed to Sign_internal) is FIPS 204 ML-DSA.Sign: with rnd = 0 it is byte-identical
/// to the crate's deterministic signature, and signatures with a random rnd also verify
#[test]
fn our_ml_dsa_sign_is_fips_204_sign() {
    let mut r = ChaCha20Rng::seed_from_u64(0x6473);
    for len in [0usize, 1, 57, 300] {
        let xi: [u8; 32] = random(&mut r);
        let msg: Vec<u8> = (0..len).map(|i| (i * 13) as u8).collect();
        let ours = pq::dsa_sign_for_tests(&xi, &msg, pq::DSA_CONTEXT, &[0u8; 32]);
        let sk = ml_dsa::SigningKey::<ml_dsa::MlDsa65>::from_seed(&xi.into());
        let theirs = sk.expanded_key().sign_deterministic(&msg, pq::DSA_CONTEXT).unwrap();
        assert_eq!(&ours[..], &theirs.encode()[..]);
        let pk = pq::dsa_public_for_tests(&xi);
        let hedged = pq::dsa_sign_for_tests(&xi, &msg, pq::DSA_CONTEXT, &random(&mut r));
        assert_ne!(hedged, ours);
        assert!(pq::dsa_verify(&pk, &msg, pq::DSA_CONTEXT, &hedged));
        assert!(!pq::dsa_verify(&pk, &msg, b"gori-corf", &hedged), "fails under a different context");
    }
}

/// Binding round trip. Flipping any single byte of ik, dh, pk_D, ds or dq fails, and a binding built over someone else's
/// pk_D fails at dq
#[test]
fn pq_sig_binding_round_trip_and_tamper() {
    let mut me = seeded(21);
    let ik = me.generate(Slot::Account);
    let b = me.pq_sig_binding().unwrap();
    assert_eq!((b.pk_d.len(), b.dh.len(), b.ds.len(), b.dq.len()), (PK_D_LEN, 32, 64, DSA_SIG_LEN));
    assert!(Core::verify_pq_sig_binding(&ik, &b.pk_d, &b.dh, &b.ds, &b.dq));
    assert_eq!(b.dh, pq::pq_sig_id(&b.pk_d));
    // ds is plain Ed25519 over "gori-core/pq-sig-bind-v1\0" ‖ ik ‖ dh
    assert!(Core::verify(&ik, &pq::bind_message(&ik, &b.dh), &b.ds));
    assert_eq!(me.sign(Slot::Account, &pq::bind_message(&ik, &b.dh)).unwrap_err(), Error::ReservedStatement);
    // Calling again yields a fresh dq only (hedged)
    let b2 = me.pq_sig_binding().unwrap();
    assert_eq!((b2.pk_d, b2.dh, b2.ds), (b.pk_d, b.dh, b.ds));
    assert_ne!(b2.dq, b.dq);

    let fields: [Vec<u8>; 5] = [ik.to_vec(), b.pk_d.to_vec(), b.dh.to_vec(), b.ds.to_vec(), b.dq.to_vec()];
    for (f, positions) in [(0usize, vec![0, 31]), (1, vec![0, 977, 1951]), (2, vec![0, 31]), (3, vec![0, 63]), (4, vec![0, 1500, 3308])] {
        for i in positions {
            let mut v = fields.clone();
            v[f][i] ^= 1;
            assert!(!Core::verify_pq_sig_binding(&v[0], &v[1], &v[2], &v[3], &v[4]), "field {f} byte {i}");
        }
    }
    for cut in 0..5 {
        let mut v = fields.clone();
        v[cut].pop();
        assert!(!Core::verify_pq_sig_binding(&v[0], &v[1], &v[2], &v[3], &v[4]), "field {cut} truncated");
    }
    // Someone else's pk_D: my identity key can honestly produce ds, but only the owner of that ML-DSA key can produce dq,
    // so reusing their dq does not verify
    let mut other = seeded(22);
    other.generate(Slot::Account);
    let ob = other.pq_sig_binding().unwrap();
    let ed = IdSeeds::from_seed(&me.slot_secret(Slot::Account).unwrap()).ed_secret;
    let ds_for_theirs = crypto::ed25519_sign(&ed, &pq::bind_message(&ik, &ob.dh));
    assert!(Core::verify(&ik, &pq::bind_message(&ik, &ob.dh), &ds_for_theirs));
    assert!(!Core::verify_pq_sig_binding(&ik, &ob.pk_d, &ob.dh, &ds_for_theirs, &ob.dq));
    assert_eq!(seeded(23).pq_sig_binding().unwrap_err(), Error::NoAccountKey);
}

// ── C boundary ──

fn take(buf: GoriBuf) -> Vec<u8> {
    let v = if buf.ptr.is_null() { Vec::new() } else { unsafe { std::slice::from_raw_parts(buf.ptr, buf.len) }.to_vec() };
    unsafe { ffi::gori_buf_free(buf) };
    v
}

fn empty() -> GoriBuf {
    GoriBuf { ptr: std::ptr::null_mut(), len: 0 }
}

#[test]
fn ffi_pq_surface() {
    unsafe {
        // Vault names
        for s in Slot::ALL {
            let p = ffi::gori_slot_vault_name(s as u32);
            assert_eq!(CStr::from_ptr(p).to_str().unwrap(), s.vault_name());
        }
        assert!(ffi::gori_slot_vault_name(4).is_null());

        let me = ffi::gori_core_new();
        let seed = [9u8; 32];
        assert_eq!(ffi::gori_load_vault(me, c"enc".as_ptr(), seed.as_ptr(), 32, std::ptr::null_mut()), Error::StaleKey as i32);
        assert_eq!(ffi::gori_load_vault(me, c"account".as_ptr(), seed.as_ptr(), 32, std::ptr::null_mut()), Error::StaleKey as i32);
        assert_eq!(ffi::gori_load_vault(me, std::ptr::null(), seed.as_ptr(), 32, std::ptr::null_mut()), Error::InvalidArgument as i32);
        let mut has = 1u8;
        assert_eq!(ffi::gori_has(me, Slot::Enc as u32, &mut has), 0);
        assert_eq!(has, 0);
        let mut pk_x = [0u8; 32];
        assert_eq!(ffi::gori_load_vault(me, c"enc-seed-v2".as_ptr(), seed.as_ptr(), 32, pk_x.as_mut_ptr()), 0);
        let mut ik = [0u8; 32];
        assert_eq!(ffi::gori_load_vault(me, c"account-seed-v2".as_ptr(), seed.as_ptr(), 32, ik.as_mut_ptr()), 0);
        assert_eq!(ik, Slot::Account.public_from(&seed));

        // HEK and es3
        let mut hek = [0u8; HEK_LEN];
        assert_eq!(ffi::gori_encryption_hybrid_key(me, std::ptr::null_mut()), Error::InvalidArgument as i32);
        assert_eq!(ffi::gori_encryption_hybrid_key(me, hek.as_mut_ptr()), 0);
        assert_eq!(&hek[PK_M_LEN..], &pk_x[..]);
        assert_eq!(ffi::gori_check_hybrid_key(hek.as_ptr(), HEK_LEN), 0);
        assert_eq!(ffi::gori_check_hybrid_key(pk_x.as_ptr(), 32), Error::NeedHybridKey as i32);
        let mut es3 = [0u8; 64];
        assert_eq!(ffi::gori_sign_encryption_key_v3(me, es3.as_mut_ptr()), 0);
        let msg = crypto::enc_key_v3_message(&hek);
        assert_eq!(ffi::gori_verify(ik.as_ptr(), 32, msg.as_ptr(), msg.len(), es3.as_ptr(), 64), 1);

        // Outer and inner envelopes
        let mut handle = [0 as std::ffi::c_char; ffi::HANDLE_BUF_LEN];
        assert_eq!(ffi::gori_create_content_key(me, handle.as_mut_ptr()), 0);
        let mut out = empty();
        assert_eq!(ffi::gori_seal_outer(me, handle.as_ptr(), 3, hek.as_ptr(), HEK_LEN, &mut out), Error::InvalidArgument as i32);
        assert_eq!(ffi::gori_seal_outer(me, handle.as_ptr(), 0, pk_x.as_ptr(), 32, &mut out), Error::NeedHybridKey as i32);
        assert_eq!(ffi::gori_seal_outer(me, handle.as_ptr(), 1, hek.as_ptr(), HEK_LEN, &mut out), 0);
        let outer = take(out);
        assert_eq!(outer.len(), OUTER_ENVELOPE_LEN);
        let mut h2 = [0 as std::ffi::c_char; ffi::HANDLE_BUF_LEN];
        assert_eq!(ffi::gori_open_outer(me, 0, outer.as_ptr(), outer.len(), h2.as_mut_ptr()), Error::NotForMe as i32);
        assert_eq!(ffi::gori_open_outer(me, 1, outer.as_ptr(), outer.len(), std::ptr::null_mut()), Error::InvalidArgument as i32);
        assert_eq!(ffi::gori_open_outer(me, 1, outer.as_ptr(), outer.len(), h2.as_mut_ptr()), 0);
        let mut out = empty();
        assert_eq!(ffi::gori_seal_inner(me, handle.as_ptr(), pk_x.as_ptr(), 32, &mut out), 0);
        let inner = take(out);
        assert_eq!(inner.len(), INNER_ENVELOPE_LEN);
        assert_eq!(ffi::gori_open_inner(me, outer.as_ptr(), outer.len(), h2.as_mut_ptr()), Error::BadEnvelope as i32);
        assert_eq!(ffi::gori_open_outer(me, 0, inner.as_ptr(), inner.len(), h2.as_mut_ptr()), Error::BadEnvelope as i32);
        assert_eq!(ffi::gori_open_inner(me, inner.as_ptr(), inner.len(), h2.as_mut_ptr()), 0);

        // Identity binding
        let (mut pk_d, mut dh, mut ds, mut dq) = ([0u8; PK_D_LEN], [0u8; 32], [0u8; 64], [0u8; DSA_SIG_LEN]);
        assert_eq!(
            ffi::gori_pq_sig_binding(me, pk_d.as_mut_ptr(), dh.as_mut_ptr(), std::ptr::null_mut(), dq.as_mut_ptr()),
            Error::InvalidArgument as i32
        );
        assert_eq!(ffi::gori_pq_sig_binding(me, pk_d.as_mut_ptr(), dh.as_mut_ptr(), ds.as_mut_ptr(), dq.as_mut_ptr()), 0);
        let ok = |dq: &[u8]| {
            ffi::gori_verify_pq_sig_binding(ik.as_ptr(), 32, pk_d.as_ptr(), PK_D_LEN, dh.as_ptr(), 32, ds.as_ptr(), 64, dq.as_ptr(), dq.len())
        };
        assert_eq!(ok(&dq), 1);
        assert_eq!(ok(&dq[..DSA_SIG_LEN - 1]), 0);
        assert_eq!(ffi::gori_verify_pq_sig_binding(std::ptr::null(), 32, pk_d.as_ptr(), PK_D_LEN, dh.as_ptr(), 32, ds.as_ptr(), 64, dq.as_ptr(), DSA_SIG_LEN), 0);
        assert!(!ffi::gori_error_message(Error::StaleKey as i32).is_null());
        assert!(!ffi::gori_error_message(Error::NeedHybridKey as i32).is_null());
        ffi::gori_core_free(me);
    }
}

// ── Cross-implementation vectors (opened by the JavaScript reference implementation) ──

#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
#[serde(rename_all = "camelCase")]
struct Envelope {
    purpose: u32,
    /// HKDF context (string)
    info: String,
    /// Sealed content key (32)
    key: String,
    /// Encapsulation randomness m (32) ‖ ephemeral X25519 secret (32)
    eseed: String,
    nonce: String,
    envelope: String,
}

#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
#[serde(rename_all = "camelCase")]
struct Case {
    /// Encryption seed (Slot::Enc) and identity seed (Slot::Account)
    enc_seed: String,
    account_seed: String,
    pk_x: String,
    hek: String,
    kid: String,
    ik: String,
    es3: String,
    pk_d: String,
    dh: String,
    ds: String,
    /// FIPS 204 rnd (32) for dq: the same rnd gives the same bytes
    dq_rnd: String,
    dq: String,
    envelopes: Vec<Envelope>,
}

#[derive(Serialize, Deserialize, Debug, PartialEq, Clone)]
struct Fixture {
    generator: String,
    cases: Vec<Case>,
}

fn generate() -> Fixture {
    let mut r = ChaCha20Rng::seed_from_u64(0x7071_2d76);
    let cases = (0..3)
        .map(|_| {
            let enc_seed: [u8; 32] = random(&mut r);
            let account_seed: [u8; 32] = random(&mut r);
            let key: [u8; 32] = random(&mut r);
            let dq_rnd: [u8; 32] = random(&mut r);
            let draws: Vec<([u8; 64], [u8; 24])> = (0..3).map(|_| (random(&mut r), random(&mut r))).collect();
            let mut stream = key.to_vec();
            stream.extend_from_slice(&[0u8; 16]); // handle name
            for (e, n) in &draws {
                stream.extend_from_slice(e);
                stream.extend_from_slice(n);
            }
            stream.extend_from_slice(&dq_rnd);
            let mut c = Core::with_rng(Box::new(Replay(stream)));
            c.load(Slot::Enc, &enc_seed).unwrap();
            let ik = c.load(Slot::Account, &account_seed).unwrap();
            let hek = c.encryption_hybrid_key().unwrap();
            let handle = c.create_content_key();
            let envelopes = OuterPurpose::ALL
                .iter()
                .zip(&draws)
                .map(|(p, (e, n))| Envelope {
                    purpose: *p as u32,
                    info: String::from_utf8(p.info().to_vec()).unwrap(),
                    key: x(&key),
                    eseed: x(e),
                    nonce: x(n),
                    envelope: x(&c.seal_outer(&handle, *p, &hek).unwrap()),
                })
                .collect();
            let b = c.pq_sig_binding().unwrap();
            Case {
                enc_seed: x(&enc_seed),
                account_seed: x(&account_seed),
                pk_x: x(&c.public_key(Slot::Enc).unwrap()),
                hek: x(&hek),
                kid: x(&crypto::kid(&hek)),
                ik: x(&ik),
                es3: x(&c.sign_encryption_key_v3().unwrap()),
                pk_d: x(&b.pk_d),
                dh: x(&b.dh),
                ds: x(&b.ds),
                dq_rnd: x(&dq_rnd),
                dq: x(&b.dq),
                envelopes,
            }
        })
        .collect();
    Fixture { generator: "gori-core (Rust) tests/pq.rs, seed 0x70712d76".into(), cases }
}

fn check(f: &Fixture) {
    let who = &f.generator;
    for (i, case) in f.cases.iter().enumerate() {
        let enc_seed: [u8; 32] = arr(&case.enc_seed);
        let isd: [u8; 32] = arr(&case.account_seed);
        let keys = EncKeys::from_seed(&enc_seed);
        assert_eq!(x(&keys.hek()), case.hek, "{who}#{i}: HEK");
        assert_eq!(x(&keys.pk_x()), case.pk_x);
        let hek: [u8; HEK_LEN] = arr(&case.hek);
        assert_eq!(x(&crypto::kid(&hek)), case.kid);
        let ik: [u8; 32] = arr(&case.ik);
        assert_eq!(Slot::Account.public_from(&isd), ik, "{who}#{i}: ik");
        assert!(Core::verify(&ik, &crypto::enc_key_v3_message(&hek), &h(&case.es3)), "{who}#{i}: es3");
        let mut c = seeded(1);
        c.load(Slot::Account, &isd).unwrap();
        c.load(Slot::Enc, &enc_seed).unwrap();
        assert_eq!(x(&c.sign_encryption_key_v3().unwrap()), case.es3, "Ed25519 is deterministic");
        let id = IdSeeds::from_seed(&isd);
        assert_eq!(x(&id.pk_d()), case.pk_d, "{who}#{i}: pk_D");
        assert_eq!(x(&pq::pq_sig_id(&h(&case.pk_d))), case.dh);
        assert!(Core::verify_pq_sig_binding(&ik, &h(&case.pk_d), &h(&case.dh), &h(&case.ds), &h(&case.dq)), "{who}#{i}: binding");
        let xi: [u8; 32] = pq::id_expanded_for_tests(&isd)[32..].try_into().unwrap();
        let msg = pq::bind_message(&ik, &arr(&case.dh));
        assert_eq!(x(&pq::dsa_sign_for_tests(&xi, &msg, pq::DSA_CONTEXT, &arr(&case.dq_rnd))), case.dq, "{who}#{i}: dq bytes");
        for e in &case.envelopes {
            let p = OuterPurpose::from_u32(e.purpose).unwrap();
            assert_eq!(p.info(), e.info.as_bytes());
            let env = h(&e.envelope);
            assert_eq!(env.len(), OUTER_ENVELOPE_LEN);
            let got = crypto::open_bytes_v2(&env, &keys, p.info()).unwrap_or_else(|err| panic!("{who}#{i}: {}: {err}", e.info));
            assert_eq!(x(&got), e.key);
            assert!(c.open_outer(p, &env).is_ok());
            // Feeding the same randomness gives identical bytes
            let mut stream = h(&e.key);
            stream.extend_from_slice(&[0u8; 16]);
            stream.extend(h(&e.eseed));
            stream.extend(h(&e.nonce));
            let mut again = Core::with_rng(Box::new(Replay(stream)));
            let hd = again.create_content_key();
            assert_eq!(x(&again.seal_outer(&hd, p, &hek).unwrap()), e.envelope, "{who}#{i}: {} resealed", e.info);
        }
    }
}

#[test]
fn pq_vectors_are_reproducible_and_self_consistent() {
    let f = generate();
    check(&f);
    let path = dir().join("pq-rust.json");
    if std::env::var("GORI_WRITE_VECTORS").as_deref() == Ok("1") {
        std::fs::write(&path, serde_json::to_string_pretty(&f).unwrap() + "\n").unwrap();
    }
    let on_disk: Fixture = read_json("pq-rust.json");
    assert_eq!(on_disk, f, "pq-rust.json differs from the generator. Regenerate it with GORI_WRITE_VECTORS=1");
}

// ── Quick benchmark (desktop baseline, not on-device measurements) ──

#[test]
#[ignore = "benchmark: cargo test --release --test pq -- --ignored --nocapture measure"]
fn measure() {
    fn time<F: FnMut()>(name: &str, n: u32, mut f: F) {
        f();
        let t = Instant::now();
        for _ in 0..n {
            f();
        }
        let us = t.elapsed().as_secs_f64() * 1e6 / n as f64;
        println!("{name:<44} {us:>9.1} µs");
    }
    let mut sender = seeded(1);
    let (mut recv, hek) = receiver(2);
    let k = sender.create_content_key();
    let env = sender.seal_outer(&k, OuterPurpose::Envelope, &hek).unwrap();
    let pk_x = recv.public_key(Slot::Enc).unwrap();
    let inner = sender.seal_inner(&k, &pk_x).unwrap();
    let seed = recv.slot_secret(Slot::Enc).unwrap();
    time("encryption seed → key set (incl. ML-KEM keygen)", 200, || {
        std::hint::black_box(EncKeys::from_seed(&seed));
    });
    time("encryption_hybrid_key", 200, || {
        std::hint::black_box(recv.encryption_hybrid_key().unwrap());
    });
    time("seal_outer (HEK check + encaps + AEAD)", 200, || {
        std::hint::black_box(sender.seal_outer(&k, OuterPurpose::Envelope, &hek).unwrap());
    });
    time("open_outer (keygen + decaps + AEAD)", 200, || {
        std::hint::black_box(recv.open_outer(OuterPurpose::Envelope, &env).unwrap());
    });
    time("seal_inner (X25519, for comparison)", 200, || {
        std::hint::black_box(sender.seal_inner(&k, &pk_x).unwrap());
    });
    time("open_inner (X25519, for comparison)", 200, || {
        std::hint::black_box(recv.open_inner(&inner).unwrap());
    });
    let mut me = seeded(3);
    let ik = me.generate(Slot::Account);
    let b = me.pq_sig_binding().unwrap();
    time("public_key(Account) (SHAKE + Ed25519)", 200, || {
        std::hint::black_box(me.public_key(Slot::Account).unwrap());
    });
    time("pq_sig_binding (ML-DSA keygen + sign)", 50, || {
        std::hint::black_box(me.pq_sig_binding().unwrap());
    });
    time("verify_pq_sig_binding", 100, || {
        assert!(Core::verify_pq_sig_binding(&ik, &b.pk_d, &b.dh, &b.ds, &b.dq));
    });
}

/// Deterministic encapsulation (`encapsulate_deterministic`, `encapsulate_derand`: reusing the same randomness breaks
/// security), internal ML-DSA signing (`sign_internal`) and the test hooks (`*_for_tests`) are called only inside `src/pq.rs`.
/// The rest of the core uses only [`RecipientKey::encapsulate`] (64 bytes from our RNG). The source is scanned by identifier,
/// the same way as in the oprf `danger` feature test
#[test]
fn deterministic_pq_primitives_stay_in_pq_rs() {
    let src = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("src");
    let banned = |w: &str| {
        matches!(w, "encapsulate_deterministic" | "encapsulate_derand" | "sign_internal" | "sign_deterministic")
            || w.ends_with("_for_tests")
    };
    let mut hits = Vec::new();
    for entry in std::fs::read_dir(&src).unwrap() {
        let path = entry.unwrap().path();
        if path.extension().is_none_or(|e| e != "rs") {
            continue;
        }
        let name = path.file_name().unwrap().to_string_lossy().to_string();
        let text = std::fs::read_to_string(&path).unwrap();
        // Skip everything below #[cfg(test)] in pq.rs
        let body = if name == "pq.rs" { text.split("#[cfg(test)]").next().unwrap().to_string() } else { text };
        for (n, line) in body.lines().enumerate() {
            let code = line.split("//").next().unwrap_or("");
            for w in code.split(|c: char| !(c.is_alphanumeric() || c == '_')).filter(|w| banned(w)) {
                hits.push(format!("{name}:{}: {w}", n + 1));
            }
        }
    }
    assert!(hits.iter().all(|h| h.starts_with("pq.rs:")), "deterministic PQ primitives called outside pq.rs: {hits:?}");
    // Even inside pq.rs, deterministic encapsulation appears only as the encapsulate_derand definition and a single call
    // (from encapsulate, with our RNG)
    let derand_calls = hits.iter().filter(|h| h.ends_with(": encapsulate_derand")).count();
    assert_eq!(derand_calls, 2, "1 definition + 1 call from encapsulate: {hits:?}");
}
